INSERT INTO `ai_analysis` VALUES (13,46,2,'Overall',94.75,'Medium','{\"average\":94.75,\"min_grade\":74,\"min_subject\":\"Values Education 7\",\"subject_count\":8,\"pass_mark\":75,\"reason\":\"Overall average is 94.75, which is passing, but Values Education 7 has a grade of 74.00, which is below the passing grade of 75.00.\",\"failed_subjects\":[{\"subject_name\":\"Values Education 7\",\"grade\":74}]}','Student needs additional support. Focus on improving weakest subject(s).','2026-09-25 10:43:04');
