INSERT INTO `ai_chat_recommendations` VALUES (1,7,20,'Hi! I\'m the AI Assistant for Jhoruis Robles. Based on current grades, here are subjects that need attention:\n\n- English 7 (60.00%): Read short stories daily, keep a vocabulary journal, and practice writing short paragraphs with feedback.\n\nYou can ask me about a study schedule, parent involvement, or motivation strategies for this student.','2026-08-21 09:09:22'),(2,7,20,'A few general tips: give extra review time to English 7, encourage consistent attendance, and celebrate small improvements. You can also ask me about \'study schedule\', \'parent involvement\', or \'motivation\'.','2026-08-21 09:10:32'),(3,7,20,'Suggested weekly study plan: 30-45 minutes daily per weak subject, review notes within 24 hours after class, and a short weekly quiz to check retention.','2026-08-21 09:10:35'),(4,7,20,'Consider scheduling a parent-teacher conference to discuss performance, agree on a home study routine, and set up regular progress check-ins (weekly or bi-weekly).','2026-08-21 09:10:35'),(5,7,20,'Try small, achievable goals with positive reinforcement, peer study groups, and connect lessons to the student\'s interests to boost engagement.','2026-08-21 09:10:36'),(6,7,20,'Hi! I\'m the AI Assistant for Jhoruis Robles. Based on current grades, here are subjects that need attention:\n\n- English 7 (62.00%): Read short stories daily, keep a vocabulary journal, and practice writing short paragraphs with feedback.\n\nYou can ask me about a study schedule, parent involvement, or motivation strategies for this student.','2026-08-26 05:28:21'),(7,9,20,'Hi! I\'m the AI Assistant for Jqwd Nunez. Based on current grades, here are subjects that need attention:\n\n- Araling Panlipunan 9 (61.00%): Use timelines and concept maps to connect events, and review with flashcards before quizzes.\n\nYou can ask me about a study schedule, parent involvement, or motivation strategies for this student.','2026-08-26 07:28:37'),(8,9,20,'Try small, achievable goals with positive reinforcement, peer study groups, and connect lessons to the student\'s interests to boost engagement.','2026-08-26 07:28:43'),(9,31,21,'Hi! I\'m the AI Assistant for asd asx. Based on current grades, here are subjects that need attention:\n\n- Filipino 10 (63.00%): Magbasa ng maiikling kwento araw-araw at magsanay sa pagsulat ng maikling sanaysay o journal.\n\nYou can ask me about a study schedule, parent involvement, or motivation strategies for this student.','2026-08-27 07:59:23');
/*!40000 ALTER TABLE `ai_chat_recommendations` ENABLE KEYS */;
UNLOCK TABLES;

