  `subject_code` varchar(20) NOT NULL,
  `school_year_id` int(11) DEFAULT NULL,
  `resource_type` varchar(40) NOT NULL COMMENT 'One of the app-level AI_RESOURCE_TYPES keys (quiz, reviewer, worksheet, performance_task, rubric, study_guide, flashcards, ...). Chosen by Gemini from a fixed schema enum, not by PHP keyword matching -- validated server-side against AI_RESOURCE_TYPES before insert.',
  `title` varchar(150) NOT NULL DEFAULT '',
  `source_prompt` varchar(500) DEFAULT NULL COMMENT 'The teacher''s own request that produced this version, truncated. Context only, never displayed to the student.',
  `student_content` mediumtext NOT NULL COMMENT 'The student-safe version: questions/activity/instructions. Never includes the failing grade, "at-risk", or the correct-answer key. This is the ONLY content ever shown or sent to the student.',
  `teacher_answer_key` mediumtext DEFAULT NULL COMMENT 'Correct answers / rubric notes / explanations, teacher-facing only. Never sent to send_to_student.php, never streamed by view/download to a student session.',
  `audience` enum('student','teacher') NOT NULL DEFAULT 'student' COMMENT 'Which content this particular generated FILE was rendered from. A teacher-audience file (an answer-key copy the teacher explicitly generated for themselves) can never be attached to a student message and is never streamed to a student session, regardless of who requests it.',
  `output_format` enum('pdf','docx','gform','pptx') DEFAULT NULL COMMENT 'NULL until produced in final form. pdf/docx/pptx = a generated file under static/uploads/ai_resources/. gform = a Google Form (see google_form_* columns).',
  `google_form_id` varchar(64) DEFAULT NULL COMMENT 'The Google Form''s id (forms.body.create response formId). Set only when output_format = gform.',
  `google_form_edit_url` varchar(500) DEFAULT NULL COMMENT 'Teacher-facing Google Forms editor link (opens in the shared Google account) -- never shown to students.',
  `google_form_view_url` varchar(500) DEFAULT NULL COMMENT 'Student-facing fill-out link (the actual quiz). This is what gets delivered via Send to Student instead of a file attachment.',
  `quiz_questions_json` mediumtext DEFAULT NULL COMMENT 'The structured quiz Gemini produced for this resource -- a JSON array of {question, choices[], correct_index, points} -- used to build the Google Form and kept here so the answer key never has to be re-derived from free text.',
  `quiz_max_score` int(11) DEFAULT NULL COMMENT 'Sum of every question''s points -- the denominator for a student''s score.',
  `quiz_one_attempt` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Teacher opted in at Create Google Form Quiz time: 1 = close the Form to further responses after the first submission (see aiQuizSyncFormResponses()). 0 = unlimited attempts (original behavior).',
  `quiz_closed_at` timestamp NULL DEFAULT NULL COMMENT 'When the app called Google to close this Form after its first response, for a one-attempt quiz. NULL if not applicable or not yet closed.',
  `link_category` enum('WW','PT','QA') DEFAULT NULL COMMENT 'Assessment category the teacher chose at quiz-creation time: Written Works, Performance Tasks, or Examinations (Quarterly Assessment).',
  `link_term` enum('Term 1','Term 2','Term 3') DEFAULT NULL COMMENT 'Grading term this quiz''s score counts toward, chosen by the teacher at quiz-creation time.',
  `link_item_id` int(11) DEFAULT NULL COMMENT 'The assessment_items.item_id created for this quiz (highest_score = quiz_max_score) — the same table/shape a manually-added item in Manage Items uses. No FK constraint (see file header).',
  `grade_sync_status` enum('synced','skipped_manual_review') DEFAULT NULL COMMENT 'Result of the most recent automatic grade sync attempt for this quiz. NULL = not synced yet (no submission recorded).',
  `webhook_secret` varchar(64) DEFAULT NULL COMMENT 'Random per-form secret embedded in that form''s own Apps Script trigger and required on every gform_webhook.php callback for this resource_id -- scopes a leaked secret to a single quiz, never the whole system.',
  `stored_filename` varchar(255) DEFAULT NULL COMMENT 'Generated, unguessable filename under static/uploads/ai_resources/ -- NEVER the teacher''s prompt or the display title. Mirrors the convention already used for tutorial_plan_items.resource_file.',
  `original_filename` varchar(255) DEFAULT NULL COMMENT 'Safe, display-only file name shown in the file card / download prompt (e.g. ap8_remedial_quiz.pdf). Never used as a filesystem path.',
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` int(11) DEFAULT NULL COMMENT 'Bytes, for display.',
  `status` enum('Draft','Generated','Sent') NOT NULL DEFAULT 'Draft' COMMENT 'Draft = content exists, no file yet. Generated = a PDF/DOCX file exists on disk. Sent = attached to a student_support_messages row that has actually been sent. Generating a file never implies Sent -- only send_to_student.php sets that.',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `generated_at` timestamp NULL DEFAULT NULL COMMENT 'When the physical file was created.',
  `sent_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`resource_id`),
  KEY `idx_ai_resources_teacher` (`teacher_id`),
  KEY `idx_ai_resources_student` (`student_id`),
  KEY `idx_ai_resources_subject` (`subject_code`),
  KEY `idx_ai_resources_status` (`status`),
  KEY `idx_ai_resources_link_item` (`link_item_id`),
  CONSTRAINT `fk_ai_resources_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ai_resources_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

