INSERT INTO `ai_generated_resources` VALUES (18,20,46,'AP7',2,'practice_exercise','Summative Test 2 Review: Sinaunang Kabihasnan sa Asya','Review activity for Summative Test 2','RECAP: Ang mga sinaunang kabihasnan sa Asya (Mesopotamia, Indus, at Tsino) ay umusbong sa mga lambak-ilog dahil sa matabang lupa. Ang bawat kabihasnan ay nagkaroon ng natatanging kontribusyon tulad ng cuneiform, konsepto ng zero, at Great Wall.\r\n\r\nPANUTO: Sagutin ang mga sumusunod sa isang malinis na papel. (100 puntos)\r\n\r\nI. PAGKILALA (5 puntos bawat isa, 50 puntos total)\r\n1. Anong kabihasnan ang umusbong sa pagitan ng mga ilog Tigris at Euphrates?\r\n2. Tawag sa sistema ng pagsulat ng mga Sumerian.\r\n3. Anong ilog ang naging sentro ng kabihasnang Indus?\r\n4. Tawag sa paniniwala ng mga Tsino na ang emperador ay pinili ng langit.\r\n5. Ang tawag sa templong dambana ng mga Sumerian.\r\n6. Ano ang tawag sa sistema ng pagsulat ng mga Indus?\r\n7. Tawag sa mga lungsod-estado ng Indus na may maayos na urban planning.\r\n8. Anong dinastiya sa Tsina ang nagpatayo ng unang bahagi ng Great Wall?\r\n9. Ang tawag sa mga hari ng sinaunang Ehipto (na may ugnayan sa kasaysayan ng Asya).\r\n10. Ano ang pangunahing kabuhayan ng mga sinaunang tao sa lambak-ilog?\r\n\r\nII. PAGPAPALIWANAG (10 puntos bawat isa, 50 puntos total)\r\n11. Bakit tinawag na \'Cradle of Civilization\' ang Mesopotamia?\r\n12. Ipaliwanag ang kahalagahan ng ilog sa pag-unlad ng sinaunang kabihasnan.\r\n13. Paano nakatulong ang sistema ng pagsulat sa pamamahala ng mga sinaunang kabihasnan?\r\n14. Bakit itinuturing na maunlad ang urban planning ng Mohenjo-Daro at Harappa?\r\n15. Ano ang naging epekto ng paniniwala sa \'Mandate of Heaven\' sa Tsina?','1. Mesopotamia, 2. Cuneiform, 3. Indus, 4. Mandate of Heaven, 5. Ziggurat, 6. Pictograph/Selyo, 7. Mohenjo-Daro at Harappa, 8. Qin, 9. Pharaoh, 10. Pagsasaka/Agrikultura, 11. Dahil dito nagsimula ang unang sibilisadong lipunan, 12. Nagbibigay ng tubig at matabang lupa para sa agrikultura, 13. Para sa pagtatala ng kalakalan at batas, 14. Dahil sa maayos na sistema ng kanal at kalsada, 15. Nagbibigay ng lehitimong kapangyarihan sa emperador.','student','pdf',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'9f280bbef3a05896a6fed310bf83d1cb.pdf','summative_test_2_review_sinaunang_kabihasnan_sa_asya.pdf','application/pdf',111219,'Generated','2026-09-24 12:03:45','2026-09-24 12:03:45','2026-09-24 12:03:45',NULL),(19,20,46,'AP7',2,'practice_exercise','Summative Test 2 Review: Sinaunang Kabihasnan sa Asya','Review activity for Summative Test 2','RECAP: Ang mga sinaunang kabihasnan sa Asya (Mesopotamia, Indus, at Tsino) ay umusbong sa mga lambak-ilog dahil sa matabang lupa. Ang bawat kabihasnan ay nagkaroon ng natatanging kontribusyon tulad ng cuneiform, konsepto ng zero, at Great Wall.\r\n\r\nPANUTO: Sagutin ang mga sumusunod sa isang malinis na papel. (100 puntos)\r\n\r\nI. PAGKILALA (5 puntos bawat isa, 50 puntos total)\r\n1. Anong kabihasnan ang umusbong sa pagitan ng mga ilog Tigris at Euphrates?\r\n2. Tawag sa sistema ng pagsulat ng mga Sumerian.\r\n3. Anong ilog ang naging sentro ng kabihasnang Indus?\r\n4. Tawag sa paniniwala ng mga Tsino na ang emperador ay pinili ng langit.\r\n5. Ang tawag sa templong dambana ng mga Sumerian.\r\n6. Ano ang tawag sa sistema ng pagsulat ng mga Indus?\r\n7. Tawag sa mga lungsod-estado ng Indus na may maayos na urban planning.\r\n8. Anong dinastiya sa Tsina ang nagpatayo ng unang bahagi ng Great Wall?\r\n9. Ang tawag sa mga hari ng sinaunang Ehipto (na may ugnayan sa kasaysayan ng Asya).\r\n10. Ano ang pangunahing kabuhayan ng mga sinaunang tao sa lambak-ilog?\r\n\r\nII. PAGPAPALIWANAG (10 puntos bawat isa, 50 puntos total)\r\n11. Bakit tinawag na \'Cradle of Civilization\' ang Mesopotamia?\r\n12. Ipaliwanag ang kahalagahan ng ilog sa pag-unlad ng sinaunang kabihasnan.\r\n13. Paano nakatulong ang sistema ng pagsulat sa pamamahala ng mga sinaunang kabihasnan?\r\n14. Bakit itinuturing na maunlad ang urban planning ng Mohenjo-Daro at Harappa?\r\n15. Ano ang naging epekto ng paniniwala sa \'Mandate of Heaven\' sa Tsina?','1. Mesopotamia, 2. Cuneiform, 3. Indus, 4. Mandate of Heaven, 5. Ziggurat, 6. Pictograph/Selyo, 7. Mohenjo-Daro at Harappa, 8. Qin, 9. Pharaoh, 10. Pagsasaka/Agrikultura, 11. Dahil dito nagsimula ang unang sibilisadong lipunan, 12. Nagbibigay ng tubig at matabang lupa para sa agrikultura, 13. Para sa pagtatala ng kalakalan at batas, 14. Dahil sa maayos na sistema ng kanal at kalsada, 15. Nagbibigay ng lehitimong kapangyarihan sa emperador.','student','pdf',NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'b1838d5302ccbecc09498d98670fa971.pdf','summative_test_2_review_sinaunang_kabihasnan_sa_asya.pdf','application/pdf',111219,'Sent','2026-09-24 12:03:57','2026-09-24 12:03:57','2026-09-24 12:03:57','2026-09-24 12:03:57'),(20,20,46,'AP7',2,'practice_exercise','Summative Test 2 Review: Sinaunang Kabihasnan sa Asya','Review activity for Summative Test 2','RECAP: Ang mga sinaunang kabihasnan sa Asya (Mesopotamia, Indus, at Tsino) ay umusbong sa mga lambak-ilog dahil sa matabang lupa. Ang bawat kabihasnan ay nagkaroon ng natatanging kontribusyon tulad ng cuneiform, konsepto ng zero, at Great Wall.\r\n\r\nPANUTO: Sagutin ang mga sumusunod sa isang malinis na papel. (100 puntos)\r\n\r\nI. PAGKILALA (5 puntos bawat isa, 50 puntos total)\r\n1. Anong kabihasnan ang umusbong sa pagitan ng mga ilog Tigris at Euphrates?\r\n2. Tawag sa sistema ng pagsulat ng mga Sumerian.\r\n3. Anong ilog ang naging sentro ng kabihasnang Indus?\r\n4. Tawag sa paniniwala ng mga Tsino na ang emperador ay pinili ng langit.\r\n5. Ang tawag sa templong dambana ng mga Sumerian.\r\n6. Ano ang tawag sa sistema ng pagsulat ng mga Indus?\r\n7. Tawag sa mga lungsod-estado ng Indus na may maayos na urban planning.\r\n8. Anong dinastiya sa Tsina ang nagpatayo ng unang bahagi ng Great Wall?\r\n9. Ang tawag sa mga hari ng sinaunang Ehipto (na may ugnayan sa kasaysayan ng Asya).\r\n10. Ano