CREATE TABLE `classwork_assignments` (
  `assignment_id` int(11) NOT NULL AUTO_INCREMENT,
  `teacher_id` int(11) NOT NULL,
  `subject_code` varchar(20) NOT NULL,
  `section_id` int(11) NOT NULL,
  `school_year_id` int(11) NOT NULL,
  `term` varchar(20) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `category` varchar(30) NOT NULL DEFAULT 'Activity',
  `instructions` text DEFAULT NULL,
  `ai_generated` tinyint(1) NOT NULL DEFAULT 0,
  `output_format` varchar(20) DEFAULT NULL,
  `due_date` datetime DEFAULT NULL,
  `status` enum('Draft','Published','Deleted') NOT NULL DEFAULT 'Published',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `grading_category` varchar(2) DEFAULT NULL COMMENT 'WW / PT / QA from the assessment type -- never from online/offline',
  `assessment_item_id` int(11) DEFAULT NULL COMMENT 'Manage Assessment Items row the score goes to',
  `max_points` decimal(6,2) DEFAULT NULL,
  `assigned_at` datetime DEFAULT NULL,
  `answer_key` text DEFAULT NULL COMMENT 'Teacher-only answer key / rubric the AI checks against',
  `lock_after_due` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = no turn-in after the due date (teacher choice)',
  `google_form_id` varchar(100) DEFAULT NULL COMMENT 'Google Form made from the AI quiz questions',
  `google_form_edit_url` varchar(500) DEFAULT NULL COMMENT 'Teacher-only edit link (students get the responder link as an attachment)',
  `quiz_questions_json` mediumtext DEFAULT NULL COMMENT 'The reviewed AI questions the Google Form was built from',
  `topic` varchar(200) DEFAULT NULL COMMENT 'Lesson topic (shown in the student email)',
  PRIMARY KEY (`assignment_id`),
  KEY `idx_classwork_class` (`teacher_id`,`section_id`,`subject_code`,`school_year_id`,`term`),
  KEY `idx_classwork_created` (`created_at`)
