INSERT INTO `classwork_assignments` VALUES (2,20,'ENG7',45,2,'Term 1','Phillipine Poetry','Written Activity','identify or observe what is the Phillipine Poetry',0,'pdf','2026-09-24 10:40:00','Published','2026-09-24 02:41:25','2026-09-24 02:41:25','WW',199,20.00,'2026-09-24 10:41:25',NULL,0,NULL,NULL,NULL,NULL),(4,20,'ENG7',45,2,'Term 1','Phillipine poetry','Written Activity','identify and observe what is the purpose of poetry in the ph',0,'pdf','2026-09-24 19:00:00','Published','2026-09-24 10:20:17','2026-09-24 10:20:17','WW',199,20.00,'2026-09-24 18:20:17',NULL,0,NULL,NULL,NULL,NULL),(5,20,'FIL7',46,2,'Term 1','Phillipine Poetry','Written Activity','identify and purpose in poetry of the phillipines',0,'pdf','2026-09-24 19:00:00','Published','2026-09-24 10:25:01','2026-09-25 04:52:32','WW',310,50.00,'2026-09-24 18:25:01',NULL,0,NULL,NULL,NULL,NULL),(6,20,'G11GAS-LIT21',91,2,'Term 1','Phillipine Poetry','Quiz','goodluck',0,NULL,'2026-09-25 18:00:00','Published','2026-09-25 09:03:56','2026-09-25 09:03:56','WW',321,20.00,'2026-09-25 17:03:56',NULL,0,NULL,NULL,NULL,NULL),(8,20,'ENG7',45,2,'Term 1','quiz 1','Quiz','Choose the best answer for each question. Each item is worth 1 point.\n\nAnswer the Google Form below, then click Turn in.',1,'gform','2026-09-02 05:00:00','Published','2026-09-25 09:35:35','2026-09-25 09:56:31','WW',324,20.00,'2026-09-25 17:35:35','1. B, 2. True, 3. B, 4. True, 5. C, 6. True, 7. B, 8. True, 9. B, 10. False, 11. B, 12. True, 13. B, 14. False, 15. A, 16. False, 17. B, 18. True, 19. A, 20. True',0,'13R6rVPkzgHhz6dA09_kXeaB_iCXIt-u8Wx7iFZRt_8o','https://docs.google.com/forms/d/13R6rVPkzgHhz6dA09_kXeaB_iCXIt-u8Wx7iFZRt_8o/edit','[{\"question\":\"What is the primary purpose of poetry in the context of Philippine culture?\",\"choices\":[\"To entertain exclusively\",\"To preserve cultural identity and traditions\",\"To provide factual scientific data\",\"To replace written historical records\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: Philippine poetry is used to preserve oral traditions and cultural identity.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"Which of the following best describes the \'identification\' of a poem\'s themes?\",\"choices\":[\"Determining the author\'s age\",\"Finding the meaning and core subjects of the poem\",\"Counting the number of syllables\",\"Formatting the page layout\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: Poetry in the Philippines has evolved significantly from pre-colonial times to the present.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"What role does poetry play in community celebrations or social gatherings?\",\"choices\":[\"It is banned\",\"It is only for private use\",\"It acts as a medium for communal expression and storytelling\",\"It serves as a distraction\"],\"correct_index\":2,\"points\":1},{\"question\":\"True or False: Purpose refers to the specific reason or message the author wishes to convey through the poem.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"Which of these is a common characteristic of Philippine folk poetry?\",\"choices\":[\"Strict adherence to sonnet form\",\"Oral tradition and cultural reflection\",\"Focus on abstract science\",\"Lack of any emotional content\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: Understanding the context of a poem helps in identifying its true purpose.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"Why is poetry considered an important literary form for expressing national identity?\",\"choices\":[\"Because it is easy to memorize\",\"It reflects the values, struggles, and history of a people\",\"Because it is the only form of literature\",\"It is mandatory for all students\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: Most Philippine poetry is written solely for entertainment purposes without a deeper message.\",\"choices\":[\"True\",\"False\"],\"correct_index\":1,\"points\":1},{\"question\":\"What is the significance of the \'identification\' of cultural symbols in poetry?\",\"choices\":[\"To confuse the reader\",\"To connect the poem to the specific culture and values it represents\",\"To make the poem shorter\",\"To change the author\'s name\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: The purpose of a poem can change depending on its audience.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"Which element is essential for identifying the purpose of a poem?\",\"choices\":[\"The color of the ink\",\"The poet\'s intentions and the content of the lines\",\"The paper size\",\"The printer model\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: Philippine poetry is limited only to historical events.\",\"choices\":[\"True\",\"False\"],\"correct_index\":1,\"points\":1},{\"question\":\"How does identifying the tone contribute to understanding the poem\'s purpose?\",\"choices\":[\"It tells the reader how to feel about the subject\",\"It changes the spelling of words\",\"It identifies the author\'s address\",\"It is irrelevant\"],\"correct_index\":0,\"points\":1},{\"question\":\"True or False: All Philippine poems must follow a specific rigid structure to be effective.\",\"choices\":[\"True\",\"False\"],\"correct_index\":1,\"points\":1},{\"question\":\"What is often reflected in the themes of Philippine poetry?\",\"choices\":[\"Scientific formulas\",\"The daily life, values, and emotions of Filipinos\",\"Math equations\",\"Only foreign myths\"],\"correct_index\":1,\"points\":1},{\"question\":\"True or False: A poet\'s purpose can be to educate, inspire, or protest.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1},{\"question\":\"Why do we study the purpose of poetry in literature?\",\"choices\":[\"To appreciate the depth and message behind the creative work\",\"To finish the school day faster\",\"To learn how to print books\",\"Because there is no other literature\"],\"correct_index\":0,\"points\":1},{\"question\":\"True or False: The cultural background of the poet often influences the purpose of the work.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":1}]',NULL),(9,20,'G11GAS-LIT21',91,2,'Term 1','philippine poetry','Quiz','Read each question carefully and select the best answer. This quiz covers the identification and purpose of Philippine poetry.\n\nAnswer the Google Form below, then click Turn in.',1,'gform','2026-02-26 07:00:00','Published','2026-09-25 09:42:59','2026-09-25 09:56:33','WW',325,20.00,'2026-09-25 17:42:59','1. B, 2. False, 3. C, 4. True, 5. B, 6. True, 7. C, 8. False, 9. B, 10. True',0,'1jPV9pZ8WSIcTWPKlDtqiWkT8i0M14_sgjc_iwoPzm_k','https://docs.google.com/forms/d/1jPV9pZ8WSIcTWPKlDtqiWkT8i0M14_sgjc_iwoPzm_k/edit','[{\"question\":\"What is the primary purpose of early Philippine poetry as a form of oral tradition?\",\"choices\":[\"To record scientific data\",\"To pass down cultural values and history\",\"To advertise local products\",\"To teach mathematics\"],\"correct_index\":1,\"points\":2},{\"question\":\"True or False: Philippine poetry is strictly written and never oral.\",\"choices\":[\"True\",\"False\"],\"correct_index\":1,\"points\":2},{\"question\":\"Which of the following is considered a key element in identifying the theme of a poem?\",\"choices\":[\"The font size used\",\"The paper texture\",\"The imagery and message conveyed\",\"The name of the publisher\"],\"correct_index\":2,\"points\":2},{\"question\":\"True or False: Philippine poetry serves as a reflection of the Filipino identity.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":2},{\"question\":\"What is the main role of imagery in a poem?\",\"choices\":[\"To make the poem look longer\",\"To create mental pictures for the reader\",\"To confuse the reader\",\"To define the poem\'s structure\"],\"correct_index\":1,\"points\":2},{\"question\":\"True or False: Folk songs and epics are considered forms of Philippine poetry.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":2},{\"question\":\"Why do poets often use figurative language?\",\"choices\":[\"To hide the meaning of the poem\",\"To avoid grammar rules\",\"To enhance the emotional impact and depth\",\"To make it harder to read\"],\"correct_index\":2,\"points\":2},{\"question\":\"True or False: Every Philippine poem must follow a specific Western rhyming pattern.\",\"choices\":[\"True\",\"False\"],\"correct_index\":1,\"points\":2},{\"question\":\"Which of the following best describes the \'purpose\' of a poem?\",\"choices\":[\"To strictly entertain children\",\"To express thoughts, feelings, or cultural experiences\",\"To replace historical documents\",\"To provide instructions for machinery\"],\"correct_index\":1,\"points\":2},{\"question\":\"True or False: Philippine poetry has evolved from oral traditions to written literature.\",\"choices\":[\"True\",\"False\"],\"correct_index\":0,\"points\":2}]',NULL);
