INSERT INTO `student_support_messages` VALUES (38,20,46,'FIL7',2,NULL,NULL,NULL,'Classwork',NULL,NULL,'New Written Activity: Phillipine Poetry\nDue: Sep 24, 2026 7:00 PM\nOpen Classwork on this page to see the instructions and turn in your work.',NULL,'classwork','Sent',1,'2026-09-24 10:25:30','2026-09-24 10:25:02','2026-09-24 10:25:02'),(40,20,46,'AP7',2,'Medium Risk','Current Araling Panlipunan 7 grade (84.00) is below the school\'s passing mark of 75.00.',84.00,'AI Chat',NULL,'Kumusta! Narito ang isang review activity upang mas mapalalim ang iyong pag-unawa sa mga sinaunang kabihasnan sa Asya. Ang pagsagot dito ay makakatulong sa iyo na maging handa para sa susunod nating assessment. Pakisulat ang iyong mga sagot sa isang papel at ipasa ito sa susunod nating pagkikita sa klase. Kaya mo ito!','Kumusta! Narito ang isang review activity upang mas mapalalim ang iyong pag-unawa sa mga sinaunang kabihasnan sa Asya. Ang pagsagot dito ay makakatulong sa iyo na maging handa para sa susunod nating assessment. Pakisulat ang iyong mga sagot sa isang papel at ipasa ito sa susunod nating pagkikita sa klase. Kaya mo ito!',19,'ai','Sent',1,'2026-09-24 12:07:25','2026-09-24 12:03:57','2026-09-24 12:03:57'),(41,20,46,'AP7',2,'Medium Risk','Current Araling Panlipunan 7 grade (84.00) is below the school\'s passing mark of 75.00.',84.00,'AI Chat',NULL,'Kumusta! Narito ang isang review activity upang mas mapalalim ang iyong pag-unawa sa mga sinaunang kabihasnan sa Asya. Ang pagsagot dito ay makakatulong sa iyo na maging handa para sa susunod nating assessment. Pakisulat ang iyong mga sagot sa isang papel at ipasa ito sa susunod nating pagkikita sa klase. Kaya mo ito!','Word copy of \"Summative Test 2 Review: Sinaunang Kabihasnan sa Asya\".',20,'ai','Sent',1,'2026-09-24 12:07:25','2026-09-24 12:03:57','2026-09-24 12:03:57');
