INSERT INTO `teacher_ai_resource_sends` VALUES (1,4,20,2,45,'MAPEH7','Term 1','Grade 7','all','goodluck class',2,0,0,'2026-09-20 08:28:55',NULL,NULL),(2,7,20,2,45,'ENG7','Term 1','Grade 7','selected','Dear Grade 7 students, you still have a missing requirement for English 7 Term 1. This short make-up quiz replaces your missed written and oral assessment. Please complete this task in the Student Portal. Keep in mind that you can answer this quiz only once. If you have any questions or need help, please ask your teacher. Good luck!',2,0,0,'2026-09-20 18:51:38','WW',43),(3,8,20,2,47,'AP8','Term 1','Grade 8','selected','Magandang araw. Nais kong ipabatid na mayroon ka pang hindi nairerehistrong marka para sa Written/Oral Works (Q3). Ang maikling make-up quiz na ito ay inihanda upang mapunan ang naturang kakulangan. Maaari mo itong sagutan sa iyong Student Portal. Tandaan na isang beses mo lamang ito pwedeng sagutan. Kung mayroon kang mga katanungan o nangangailangan ng tulong, huwag mag-atubiling magtanong sa iyong guro. Galingan mo!',1,0,0,'2026-09-20 19:12:26','WW',49),(4,10,20,2,45,'ENG7','Term 1','Grade 7','all',NULL,2,0,0,'2026-09-23 02:44:47','WW',192),(5,12,20,2,45,'ENG7','Term 1','Grade 7','all',NULL,2,0,0,'2026-09-23 02:59:13','WW',194),(6,14,20,2,45,'MATH7','Term 1','Grade 7','all',NULL,2,0,0,'2026-09-23 06:48:40','WW',195),(8,21,20,2,45,'ENG7','Term 1','Grade 7','all','GOODLUCK YOUR PAKYO',2,0,0,'2026-09-23 11:44:12','WW',197);
