DROP TABLE IF EXISTS `teacher_ai_resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `teacher_ai_resources` (
  `resource_id` int(11) NOT NULL AUTO_INCREMENT,
  `teacher_id` int(11) NOT NULL,
  `subject_code` varchar(20) DEFAULT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `resource_type` varchar(40) NOT NULL DEFAULT 'other',
  `title` varchar(150) NOT NULL DEFAULT '',
  `source_prompt` varchar(500) DEFAULT NULL,
  `student_content` mediumtext NOT NULL,
  `teacher_answer_key` mediumtext DEFAULT NULL,
  `quiz_questions_json` mediumtext DEFAULT NULL,
  `quiz_max_score` int(11) DEFAULT NULL,
  `output_format` enum('pdf','docx','pptx','gform') DEFAULT NULL,
  `stored_filename` varchar(255) DEFAULT NULL,
  `original_filename` varchar(255) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` int(11) DEFAULT NULL,
  `google_form_id` varchar(64) DEFAULT NULL,
  `google_form_edit_url` varchar(500) DEFAULT NULL,
  `google_form_view_url` varchar(500) DEFAULT NULL,
  `status` enum('Draft','Generated','Sent') NOT NULL DEFAULT 'Draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sent_at` timestamp NULL DEFAULT NULL,
  `assessment_item_id` int(11) DEFAULT NULL COMMENT 'assessment_items.item_id this draft was generated for (Send to <item> AI).',
  PRIMARY KEY (`resource_id`),
  KEY `idx_tai_res_teacher` (`teacher_id`,`created_at`),
  KEY `idx_tai_res_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

